export default function ({ body }) {
  const id = body?.project_id ?? body?.project?.id,
    iid = body?.merge_request?.iid,
    note = body?.object_attributes?.note,
    noteId = body?.object_attributes?.id;
  const relevant =
    body?.object_kind === "note" &&
    body?.object_attributes?.noteable_type === "MergeRequest" &&
    note === "+0";
  if (!relevant) return { relevant: false, project: 0, projectText: "0", iid: 1, noteId: 0 };
  if (
    !Number.isSafeInteger(id) ||
    !Number.isSafeInteger(iid) ||
    iid <= 0 ||
    !Number.isSafeInteger(noteId)
  )
    throw Error("Missing stable GitLab note or MR identity");
  return { relevant: true, project: id, projectText: String(id), iid, noteId };
}

