export default function ({ body, project, iid }) {
  const r = body?.diff_refs;
  if (!r?.base_sha || !r?.start_sha || !r?.head_sha)
    throw Error("GitLab diff references not ready");
  return {
    refs: r,
    url: `https://gitlab.com/api/v4/projects/${project}/merge_requests/${iid}/diffs?per_page=100&page=1`,
  };
}

