export default function ({ body, status, previous, project, iid }) {
  if (status !== 200 || !Array.isArray(body)) throw Error("Invalid GitLab diff page");
  if (
    body.some(
      (x) =>
        x?.too_large ||
        x?.collapsed ||
        (!x?.deleted_file && !x?.renamed_file && typeof x?.diff !== "string"),
    )
  )
    throw Error("GitLab omitted one or more diffs");
  const page = (previous?.page ?? 0) + 1,
    files = [...(previous?.files ?? []), ...body],
    more = body.length === 100;
  return {
    state: { page, files },
    more,
    url: `https://gitlab.com/api/v4/projects/${project}/merge_requests/${iid}/diffs?per_page=100&page=${page + 1}`,
  };
}

