export default function ({ files, previous }) {
  let i = previous?.index ?? 0;
  while (
    i < files.length &&
    (files[i].renamed_file || files[i].deleted_file || !files[i].diff?.startsWith("@@"))
  )
    i++;
  const more = i < files.length,
    x = more ? files[i] : { diff: "", old_path: "", new_path: "" };
  let old = 0,
    now = 0,
    position = null;
  for (const line of x.diff.split("\n")) {
    const m = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(line);
    if (m) {
      old = +m[1];
      now = +m[2];
      continue;
    }
    if (line.startsWith("+")) {
      position = { new_line: now };
      now++;
    } else if (line.startsWith("-")) {
      position = { old_line: old };
      old++;
    } else if (line.startsWith(" ")) {
      old++;
      now++;
    }
  }
  if (more && !position) throw Error("No changed line to anchor review");
  return { state: { index: i + 1 }, more, file: x, position: position ?? {} };
}

