export default async function ({ noteId, refs, file, position, review, project, iid }, ctx) {
  const key = "gitlab-review:" + JSON.stringify([noteId, refs.head_sha, file.new_path]);
  const s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect GitLab discussion before retrying");
  if (s?.status === "done") return { skip: true, key, url: "https://gitlab.com/", body: {} };
  if (!review?.comment?.trim()) return { skip: true, key, url: "https://gitlab.com/", body: {} };
  await ctx.state.set(key, { status: "pending" });
  return {
    skip: false,
    key,
    url: `/projects/${project}/merge_requests/${iid}/discussions`,
    body: {
      body: review.comment,
      position: {
        position_type: "text",
        old_path: file.old_path,
        new_path: file.new_path,
        start_sha: refs.start_sha,
        head_sha: refs.head_sha,
        base_sha: refs.base_sha,
        ...position,
      },
    },
  };
}

